 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Arjun. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hi Arjun, I'm Aisha Nair. I'm calling because my latest bill is completely wrong and I'm honestly fed up with these constant errors.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I need your account number to access the details.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "It is 63428001.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "I see the charge. What is the issue?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "You've charged me twice for the international roaming package. I'm tired of this. I'm just going to cancel my service and switch to another provider.",
      "tags": [
        "churn_signal"
      ]
    },
    {
      "speaker": "agent",
      "text": "I will raise a refund request for the duplicate charge now.",
      "tags": [
        "action:refund_request"
      ]
    },
    {
      "speaker": "customer",
      "text": "Fine, but I still want to cancel. I live at 326 Brigade Road and my phone is 95213 13640.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Any refund or credit is subject to approval and will take 7 to 10 business days to process. Regarding the cancellation, there is no early termination fee, and your final bill will arrive in the next billing cycle.",
      "tags": [
        "disclosure"
      ]
    },
    {
      "speaker": "customer",
      "text": "Okay. I also have an outstanding balance of twenty dollars that I want to pay now so there are no issues.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Provide the card details.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "It is four one three seven two one five nine zero one zero nine two eight one nine.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Payment processed. I will now process the cancellation request for your account.",
      "tags": [
        "action:cancellation_or_retention"
      ]
    },
    {
      "speaker": "customer",
      "text": "Alright, that's all I needed.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Is there anything else I can assist you with? I have requested the refund and processed your cancellation. Goodbye.",
      "tags": [
        "closure"
      ]
    }
  ]
}
